  "analysis": "选 B：数字存储要求“高擦写次数”，不是低擦写次数。",
  "source": "模拟题.pdf p7",
  "analysisFull": "①数字存储技术要求：高存储密度、高数据传输率、高存储寿命、低功耗、高擦写次数（可反复读写）、快速寻址。②B 项“低擦写次数”与要求相反，故不是数字存储的要求。③存储器分类：磁存储（硬盘）、光存储（光盘）、半导体存储（闪存、DRAM），各有擦写寿命指标。④易错：把“低”与“高”看反（选择题常见反向陷阱）。",
