  "analysisFull": "①近程结构：化学组成、连接方式、空间构型、序列结构、支化与交联。②取向态结构属聚集态结构（链段/分子链/晶粒沿力方向排列）。③易错：把“空间构型”（近程）与“取向态”（聚集态）混淆；记住近程只描述单个链的化学与构型。",
  "paper": "模拟卷三",
