  "analysisFull": "①短路扩散：沿表面、晶界、位错快速扩散（A 对）。②低温时体扩散极慢，主要进行短路扩散（B 对）。③高温时体（晶格）扩散占主导（C 对）。④不同温区主导机制不同（D 表述与前三项矛盾，故为错误项）。⑤易错：把“低温主导短路、高温主导体扩散”记反；漏“激活能差异”这一原因。",
