  "analysisFull": "①金属化合物（金属间化合物）：由金属与金属或金属与类金属以金属键/共价键结合、具有不同于组元的固有结构，如 Fe3C（间隙化合物）、Cu5Zn8（电子化合物）、LaNi5（储氢合金中的金属间化合物）。②SiC 是硅与碳以共价键结合的无机非金属化合物（陶瓷/磨料/半导体材料），不具备金属特性，故不是金属化合物。③易错：把“含金属元素的化合物”都当金属化合物（SiC 不含金属元素，且键型为共价）。"
