  "analysisFull": "①7 晶系 14 种布拉维点阵的分布：三斜 1、单斜 2（简单+底心）、正交 4（简单、底心、体心、面心）、四方 2（简单、体心）、六方 1、菱方 1、立方 3（简单、体心、面心）。②故含四种点阵的是正交晶系（A）。③立方晶系只有 3 种（底心立方因破坏立方对称而不存在）。④易错：把“立方 3 种”当四种；把“四方 2 种”记成 4 种。"
