  "analysisFull": "①主链（C—C、C—O、C—N 等）为共价键，决定链强度。②分子间为范德华力/氢键（C、D 是分子间作用）。③离子键（A）不存在于常见碳链高分子。④易错：混淆“分子内”与“分子间”。"
