   "界面过弱时载荷不能有效传递给增强体，过强时纤维拔出减少、断裂韧性下降，故应取适度结合",
   "界面结合越强越好，可使强度与韧性同时达到最高",
   "界面结合强度只影响复合材料的耐热性，与力学性能无关",
   "界面结合越弱，裂纹越易偏转，材料强度越高"
