  "stem": "材料按化学组成和显微结构特点分为金属材料、无机非金属材料、高分子材料和复合材料四大类；前三种材料的显微结构相对均一，而复合材料是由两种或两种以上性质不同的材料复合而成的______材料，其性能取决于基体、增强体和______的共同作用。",
