  "stem": "纳米材料是指在三维空间中至少有一维处于______nm 尺度范围或由它们作为基本单元所构成的材料；其中纳米微粒处于簇与微粉之间，故又称______；由纳米微粒、纳米丝或纳米管按人们的意愿排列组装而成的体系称为纳米______体系。",
