  "topic": "自创模拟题·卷二",
  "paper": "自创模拟卷二",
  "paperNo": 15,
  "type": "single",
  "difficulty": 3,
  "stem": "制备金属基复合材料时，液态金属对陶瓷增强体的润湿角大于 90°（不润湿）。由此可以判断（　）",
